{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Verapamil absolute bioavailability in normal subjects was 22.0% using simultaneous IV and oral dosing, supporting F ≥ 20% with high transferability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Verapamil bioavailability averaged 19.4% in 20 normal young men after single oral doses versus IV, a borderline sub-20% value that is contradictory but close to the threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Praziquantel oral bioavailability was 27.2 ± 5.4% in patients with hepatic disease, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Noscapine absolute oral bioavailability was 30% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Sulpiride absolute oral bioavailability was 0.340 ± 0.125 after 300 mg capsules versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Encainide absolute oral bioavailability was 32 ± 7% in normal subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Five high-transfer analogues show absolute oral bioavailability consistently at or above 20% (verapamil ~22%, praziquantel 27%, noscapine 30%, sulpiride 27-34%, encainide 30-42%). The only sub-20% values are borderline verapamil estimates (18-20% and 19.4%). The weight of direct experimental evidence supports a high F ≥ 20% prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "Exact structural relationship between the query and the analogue molecules is not provided.",
    "Verapamil values straddle the 20% threshold, introducing borderline uncertainty.",
    "Some analogue measurements were made in disease states (e.g., cirrhosis, hepatic disease) and may not reflect normal oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

